function cardHead(title,sub,action){return '<div class="sectionhead"><div><h2>'+title+'</h2>'+(sub?'<p class="sub">'+sub+'</p>':'')+'</div>'+(action?'<button class="round" data-add="'+action+'" aria-label="'+esc(title)+' hinzufügen">+</button>':'')+'</div>'}
function render(){if(!state||window.Vault?.locked)return;applyTheme();const x=calc(),p=pages[tab];document.getElementById('eyebrow').textContent=p[0];document.getElementById('pagetitle').textContent=p[1];document.getElementById('pagesub').textContent=p[2];document.getElementById('nav').innerHTML=tabs.map(t=>'<button data-tab="'+t[0]+'" class="'+(tab===t[0]?'active':'')+'" aria-current="'+(tab===t[0]?'page':'false')+'">'+icon(t[1],17)+t[2]+'</button>').join('');document.getElementById('sample').innerHTML=(loadError?'<div class="alert">Ein bestehender lokaler Plan konnte nicht geladen werden oder die Speicherung ist gesperrt. Vorhandene Daten wurden beim Start nicht überschrieben. Du kannst eine Sicherung importieren.</div>':'')+(state.demo?'<div class="demo"><div><b>Entdecke deine Planung.</b><br>Alle Beträge sind veränderbare Beispieldaten.</div><button class="textbtn" data-action="clear">Mit eigenen Daten starten ↗</button></div>':'');document.getElementById('saved').textContent=storageOK?'Auf diesem Gerät gespeichert':'Nur in dieser Sitzung';document.getElementById('storagefoot').textContent=storageOK?'Deine Eingaben bleiben in diesem Browser. Sichere sie regelmäßig über das Export-Symbol.':'Keine dauerhafte Speicherung verfügbar. Sichere deine Eingaben über das Export-Symbol.';document.getElementById('content').innerHTML=({overview,plan,distribute,reserve,forecast}[tab])(x)}
function budgetCard(k,name,ic,x){const b=x.b[k],s=x.spent[k],r=x.remain[k],rawOver=k!=='s'&&s>x.original[k]+.005,bad=r<-.005;let hint='';if(k==='e'&&x.transfer>0)hint=euro(x.transfer)+' aus Wealth';if(k==='g'&&x.transfer<0)hint=euro(-x.transfer)+' aus Essentials';if(k==='e'&&x.transfer<0)hint=euro(-x.transfer)+' an Wealth';if(k==='g'&&x.transfer>0)hint=euro(x.transfer)+' an Essentials';if(k==='s')hint=x.distributing?'Auf Lifestyle & Wealth verteilt':'Für deinen Notgroschen reserviert';return '<div class="budget '+(bad?'warningborder':'')+'"><div class="budgettop"><span class="budgetname">'+name+'</span><span style="color:'+C[k]+'">'+icon(ic,18)+'</span></div><small>'+(k==='s'?'Monatlicher Beitrag':'Noch verfügbar')+'</small><div class="big '+(bad?'negative':'')+'">'+euro(k==='s'?s:r)+'</div><div class="bar"><span style="width:'+Math.max(0,Math.min(100,b>0?s/b*100:s>0?100:0))+'%;background:'+(bad?'var(--red)':C[k])+'"></span></div><div class="pair"><span>Budget nach Ausgleich</span><b>'+euro(b)+'</b></div><div class="pair"><span>'+(k==='s'?'Vorgesehen':'Verplant')+'</span><span>'+euro(s)+'</span></div><div class="tiny" style="margin-top:9px">'+(hint||number(x.income?x.original[k]/x.income*100:({e:50,s:15,r:10,g:25}[k]))+' % des Einkommens')+'</div>'+(rawOver?'<span class="badgelabel warn">Ursprüngliches Budget überschritten</span>':'')+'</div>'}
function ring(x){let offset=0;const parts=['e','s','r','g'].map(k=>{const pc=x.income?x.original[k]/x.income*100:({e:50,s:15,r:10,g:25}[k]),t='<circle cx="70" cy="70" r="53" fill="none" stroke="'+C[k]+'" stroke-width="13" pathLength="100" stroke-dasharray="'+Math.max(0,pc-.8)+' '+(100-Math.max(0,pc-.8))+'" stroke-dashoffset="'+(-offset)+'" transform="rotate(-90 70 70)"/>';offset+=pc;return t}).join('');return '<div class="ringwrap"><svg class="ring" viewBox="0 0 140 140" role="img" aria-label="Verteilung des monatlichen Einkommens">'+parts+'<text x="70" y="68" text-anchor="middle" font-size="20" font-weight="650" fill="#17191c">100 %</text><text x="70" y="84" text-anchor="middle" font-size="9" fill="#9096a0">DEIN PLAN</text></svg><div class="legend">'+Object.entries(B).map(([k,n])=>'<div><i class="dot" style="background:'+C[k]+'"></i><b>'+number(x.income?x.original[k]/x.income*100:({e:50,s:15,r:10,g:25}[k]))+' %</b> '+n+'</div>').join('')+'</div></div>'}
function overview(x){const shortage=x.remain.e+x.remain.g;return '<section class="card hero"><div><p class="eyebrow">Dein monatliches Nettoeinkommen</p><div class="huge">'+euro(x.income)+'</div><div class="available '+(x.free<-.005?'negative':'')+'">'+icon(x.free<0?'wallet':'trend',17)+'<b>'+euro(x.free)+'</b> '+(x.free<0?'insgesamt überplant':'noch unverplant')+(x.free>=.005?'<small class="happy-surplus">JUHUU 🐭</small>':'')+'</div><p class="tiny" style="margin-top:12px">Rest aus Essentials und Wealth. Lifestyle und Safety sind separat reserviert.</p></div>'+ring(x)+'</section>'+(shortage<-.005?'<div class="alert">Essentials und Wealth sind zusammen um <b>'+euro(-shortage)+'</b> überplant. Der gegenseitige Ausgleich reicht nicht aus.</div>':'')+(x.remain.r<-.005?'<div class="alert">Lifestyle ist um <b>'+euro(-x.remain.r)+'</b> überplant.</div>':'')+'<div class="budgetgrid">'+[['e','Essentials','home'],['s','Safety','shield'],['r','Lifestyle','gift'],['g','Wealth','trend']].map(([k,n,ic])=>budgetCard(k,n,ic,x)).join('')+'</div><div class="grid"><section class="card">'+cardHead('Dein Sicherheitspolster','Notgroschen · '+({3:'Basis',5:'Komfort',7:'Maximum'}[state.safety]))+'<div class="big">'+euro(state.reserve)+'</div><p class="subtitle">von '+euro(x.target)+' Zielbetrag</p><div class="bar progresswide"><span style="width:'+(x.target?Math.min(100,state.reserve/x.target*100):0)+'%;background:#a18ada"></span></div><div class="pair"><span>'+(x.full?'Ziel erreicht':'Noch bis zum Ziel')+'</span><b>'+euro(Math.max(0,x.target-state.reserve))+'</b></div><button class="textbtn" style="margin-top:16px" data-tab="reserve">Notgroschen verwalten ↗</button></section><section class="card">'+cardHead('Dein ETF-Sparplan','Dein eigener Vermögensaufbau')+'<div class="big">'+euro(state.portfolio)+'</div><p class="subtitle">aktueller Depotwert</p><div class="rule"></div><div class="pair"><span>Monatliche Sparrate</span><b>'+euro(state.rate)+'</b></div><div class="pair"><span>Verteilung</span><span>'+state.funds.length+' ETF'+(state.funds.length===1?'':'s')+'</span></div><button class="textbtn" style="margin-top:16px" data-tab="forecast">Zukunft berechnen ↗</button></section><section class="card fullwidth">'+cardHead('Bereit für den Monatsanfang?','Alle Konten und Überweisungsbeträge an einem Ort.')+'<button class="textbtn" data-tab="distribute">Einkommensverteiler öffnen ↗</button></section></div>'}
const budgetFor={essentials:'e',rewards:'r',growth:'g'};
function entries(key){return state[key].map(r=>{let sub='',active=true;if(['essentials','rewards'].includes(key)&&r.installment){active=activeExpense(r);sub=r.start>month()?'Start '+monthLabel(r.start):installmentEnd(r)<month()?'Abgeschlossen':'Rate bis '+monthLabel(installmentEnd(r));sub+=' · '+r.duration+' Monate';const rest=installmentRemaining(r);sub+=' · Rest: '+euro(rest.amount)+' · '+rest.count+' Rate'+(rest.count===1?'':'n')+' offen';if(!active)sub+=' · aktuell nicht eingeplant'}else sub=key==='incomes'?'Monatlicher Nettoeingang':'Monatlich';if(key!=='incomes'&&r.shared)sub+=' · '+euro(r.amount)+' gesamt · dein Anteil 50 %';if(key!=='incomes')sub+=' · '+accountName(r.account||state.budgetAccounts[budgetFor[key]]);return '<div class="row"><span class="entryicon">'+icon(r.icon)+'</span><div class="entrycopy"><div class="entryname">'+esc(r.name)+'</div><div class="entrysub">'+esc(sub)+'</div></div><span class="money" style="'+(!active?'color:#a2a7af':'')+'">'+euro(key==='incomes'?r.amount:personalAmount(r))+'</span><button class="editbtn" data-edit="'+key+':'+r.id+'" aria-label="'+esc(r.name)+' bearbeiten">'+icon('edit',15)+'</button></div>'}).join('')||'<div class="empty">Noch keine Einträge. Mit + legst du den ersten an.</div>'}
function listCard(key,title,sub,total){return '<section class="card">'+cardHead(title,sub,key)+entries(key)+'<div class="total"><span>Monatlich gesamt</span><span>'+euro(total)+'</span></div></section>'}
function accountOptions(selected,inherited){return (inherited?'<option value="" '+(!selected?'selected':'')+'>Budgetkonto · '+esc(accountName(inherited))+'</option>':'')+getAccounts().map(a=>'<option value="'+a.id+'" '+(selected===a.id?'selected':'')+'>'+esc(a.name)+'</option>').join('')}
function plan(x){const totalP=state.funds.reduce((a,f)=>a+f.percent,0),colors=['#167c62','#76ab93','#a18ada','#5480df','#ddae65'];return '<div class="grid"><div class="stack">'+listCard('incomes','Einkommen','Alle monatlichen Netto-Einnahmen',x.income)+listCard('essentials','Essentials','50 % · dein Alltag',x.spent.e)+listCard('rewards','Lifestyle','10 % · Dinge, die Freude machen',x.spent.r)+'</div><div class="stack"><section class="card">'+cardHead('Dein ETF-Sparplan','Wealth · nur dein eigener Sparplan')+'<div class="field"><label for="etfrate">Monatliche Gesamtsparrate</label><div class="inputwrap"><input id="etfrate" inputmode="decimal" data-number="rate" value="'+state.rate+'"><span class="suffix">€</span></div></div><div class="field"><label for="etfaccount">Konto für die ETF-Sparrate</label><select id="etfaccount">'+accountOptions(state.etfAccount,state.budgetAccounts.g)+'</select></div><div class="sectionhead" style="margin-top:25px"><h3>Deine ETF-Aufteilung</h3><button class="round" data-add="funds" aria-label="ETF hinzufügen">+</button></div>'+(totalP?'<div class="allocationbar">'+state.funds.map((f,i)=>'<span style="width:'+(f.percent/totalP*100)+'%;background:'+colors[i%colors.length]+'"></span>').join('')+'</div>':'')+state.funds.map((f,i)=>'<div class="row"><span class="dot" style="background:'+colors[i%colors.length]+'"></span><div class="entrycopy"><div class="entryname">'+esc(f.name)+'</div><div class="entrysub">'+euro(state.rate*f.percent/100)+' monatlich</div></div><span class="money">'+number(f.percent)+' %</span><button class="editbtn" data-edit="funds:'+f.id+'" aria-label="'+esc(f.name)+' bearbeiten">'+icon('edit',15)+'</button></div>').join('')+(!state.funds.length?'<p class="empty">Hinterlege deine ETFs und ihre prozentualen Anteile.</p>':'')+'<div class="total"><span>Anteile gesamt</span><span class="'+(Math.abs(totalP-100)>.01?'negative':'positive')+'">'+number(totalP)+' %</span></div>'+(Math.abs(totalP-100)>.01?'<div class="alert" style="margin-top:15px;margin-bottom:0">Die ETF-Anteile müssen zusammen 100 % ergeben. Die Gesamtsparrate zählt unabhängig davon einmal zum Wealth-Budget.</div>':'')+'</section>'+listCard('growth','Weitere Wealth-Anlagen','Altersvorsorge, VL, Gold und mehr',expenseSum(state.growth))+'<section class="card"><div class="pair"><span>ETF-Sparplan</span><b>'+euro(state.rate)+'</b></div><div class="pair"><span>Weitere Wealth-Anlagen</span><b>'+euro(expenseSum(state.growth))+'</b></div><div class="total"><span>Wealth insgesamt</span><span>'+euro(x.spent.g)+'</span></div><p class="info">Weitere Wealth-Anlagen zählen zum Budget, aber nicht zur ETF-Prognose. Jede Einnahme und jeden Sparbeitrag nur einmal erfassen.</p></section></div></div>'}
function accountDistribution(x){const result=Object.fromEntries(getAccounts().map(a=>[a.id,{amount:0,lines:[]}]));function add(account,budget,name,amount){if(Math.abs(amount)<.0000001)return;result[account].amount+=amount;result[account].lines.push({budget,name,amount})}for(const k of ['e','s','r','g']){const fallback=state.budgetAccounts[k];let items=[];if(k==='e')items=state.essentials.filter(activeExpense);if(k==='r')items=state.rewards.filter(activeExpense);if(k==='g')items=[{name:'ETF-Sparplan',amount:state.rate,account:state.etfAccount},{name:'Altersvorsorgedepot',amount:state.retirement.rate,account:state.retirement.account},...state.growth];if(k==='s')items=[{name:'Notgroschen',amount:x.b.s,account:''}];let planned=0;for(const item of items){const amount=personalAmount(item);planned+=amount;add(item.account||fallback,k,item.name+(item.shared?' · dein Anteil (50 %)':''),amount)}const rest=x.b[k]-planned;if(Math.abs(rest)>.0000001)add(fallback,k,rest>=0?'Noch unverplant':'Budgetunterdeckung',rest)}return result}
function distribute(x){const dist=accountDistribution(x),blocked=['e','r','g'].some(k=>x.remain[k]<-.005),transfers=getAccounts().filter(a=>a.id!=='giro'&&dist[a.id].amount>.005),totalTransfers=transfers.reduce((s,a)=>s+dist[a.id].amount,0);return (blocked?'<div class="alert"><b>Deine Verteilung braucht noch einen Ausgleich.</b><br>Mindestens ein Budget ist überplant. Negative Restbeträge sind in den Kontodetails markiert. Passe die Planung an, bevor du die Überweisungsbeträge übernimmst.</div>':'')+'<div class="grid"><div class="stack"><section class="card darkcard"><p class="eyebrow">Monatlicher Eingang · Girokonto</p><div class="huge">'+euro(x.income)+'</div><div class="rule"></div><div class="pair"><span>Auf andere Konten verteilen</span><b>'+euro(totalTransfers)+'</b></div><div class="pair"><span>Auf dem Girokonto bereitstellen</span><b class="'+(dist.giro.amount<-.005?'negative':'')+'">'+euro(dist.giro.amount)+'</b></div><p class="tiny" style="margin-top:16px">Der Verteiler geht davon aus, dass dein gesamtes Einkommen zunächst auf deinem Girokonto liegt.</p></section><section class="card">'+cardHead('Deine Überweisungsübersicht',blocked?'Vorläufige Beträge · bitte Unterdeckungen klären':'Diese Beträge monatlich vom Girokonto verteilen')+(transfers.length?transfers.map((a,i)=>'<div class="transferrow"><span class="stepnum">'+(i+1)+'</span><div class="entrycopy"><div class="entryname">'+esc(a.name)+'</div><div class="entrysub">Girokonto → '+esc(a.name)+'</div></div><b class="money">'+euro(dist[a.id].amount)+'</b></div>').join(''):'<p class="empty">Aktuell ist keine Überweisung auf ein anderes Konto vorgesehen.</p>')+'<div class="total"><span>Überweisungen gesamt</span><span>'+euro(totalTransfers)+'</span></div><div class="status">'+euro(dist.giro.amount)+' bleiben auf dem Girokonto eingeplant – zum Beispiel für Sparraten oder Ausgaben.</div><p class="info">Monatliche Zuweisungen, keine Kontostände. Vorhandene Guthaben und ausgeführte Überweisungen werden nicht verrechnet.</p></section></div><div class="stack"><section class="card">'+cardHead('Standardkonto je Budget','Gilt für alle Einträge ohne eigene Kontoauswahl.')+'<div class="budgetsetting">'+Object.entries(B).map(([k,n])=>'<div class="field"><label for="budgetaccount-'+k+'"><span class="dot" style="background:'+C[k]+'"></span>'+n+'</label><select id="budgetaccount-'+k+'" data-budgetaccount="'+k+'">'+accountOptions(state.budgetAccounts[k])+'</select></div>').join('')+'</div><p class="info">Noch unverplantes Budget wird ebenfalls auf dem Standardkonto bereitgestellt. Einzelne Ausgaben und Sparraten können unter „Planung“ ein anderes Konto erhalten.</p><button class="textbtn" style="margin-top:10px" data-tab="plan">Einträge und Konten bearbeiten ↗</button></section><section class="card"><div class="accountheading"><div><h2>Deine Konten</h2><p class="subtitle" style="margin-top:5px">Antippen, um die Aufteilung zu sehen.</p></div><span class="pill">'+new Date().toLocaleDateString('de-DE',{month:'long'})+'</span></div>'+getAccounts().map(a=>{const d=dist[a.id];return '<details class="account"><summary class="accountsummary"><span class="entryicon" style="color:'+a.color+';background:'+a.color+'12">'+icon(a.icon)+'</span><span class="entrycopy"><span class="entryname">'+esc(a.name)+'</span><span class="entrysub" style="display:block">'+(a.id==='giro'?'Auf dem Girokonto lassen':'Vom Girokonto überweisen')+'</span></span><b class="money '+(d.amount<-.005?'negative':'')+'">'+euro(d.amount)+'</b><span class="chevron">›</span></summary><div class="accountdetail">'+(d.lines.length?d.lines.map(l=>'<div class="pair"><span><i class="dot" style="display:inline-block;width:5px;height:5px;background:'+C[l.budget]+';margin-right:5px"></i>'+esc(l.name)+'<br><span style="font-size:10px;margin-left:10px">'+B[l.budget]+'</span></span><b class="'+(l.amount<0?'negative':'')+'">'+euro(l.amount)+'</b></div>').join(''):'<p class="tiny">Diesem Konto ist aktuell kein Betrag zugeordnet.</p>')+'</div></details>'}).join('')+'<div class="total"><span>Gesamtes Einkommen verteilt</span><span>'+euro(Object.values(dist).reduce((s,a)=>s+a.amount,0))+'</span></div></section>'+accountManager()+'</div></div><div class="transfernote">'+icon('transfer',18)+'<span>Der Ausgleich zwischen Essentials und Wealth sowie deine aktive Safety-Verteilung werden automatisch berücksichtigt. Es werden keine Überweisungen ausgelöst.</span></div>'}
function reserve(x){const missing=Math.max(0,x.target-state.reserve),eta=x.b.s>0?Math.ceil(missing/x.b.s):null;return '<div class="grid"><section class="card">'+cardHead('Deine Sicherheitsstufe','Gesamtes Nettoeinkommen × Anzahl Monate')+'<div class="segmented">'+[[3,'Basis'],[5,'Komfort'],[7,'Maximum']].map(([v,n])=>'<button data-safety="'+v+'" class="'+(state.safety===v?'active':'')+'" aria-pressed="'+(state.safety===v)+'">'+n+'<small>'+v+' Monate</small></button>').join('')+'</div><small>Erforderlicher Notgroschen</small><div class="huge" style="font-size:39px">'+euro(x.target)+'</div><p class="tiny">'+euro(x.income)+' monatliches Netto × '+state.safety+'</p><div class="field"><label for="reservevalue">Aktueller Stand deines Notgroschens</label><div class="inputwrap"><input id="reservevalue" data-number="reserve" inputmode="decimal" value="'+state.reserve+'"><span class="suffix">€</span></div></div><div class="bar progresswide"><span style="width:'+(x.target?Math.min(100,state.reserve/x.target*100):0)+'%;background:#a18ada"></span></div><div class="statrow"><div><small>Noch erforderlich</small><p class="value">'+euro(missing)+'</p></div><div><small>Fortschritt</small><p class="value">'+(x.target?Math.round(state.reserve/x.target*100):0)+' %</p></div></div>'+(x.income===0?'<p class="info">Trage zuerst dein Einkommen ein.</p>':x.full?'<div class="status">Dein Sicherheitspolster ist aufgebaut. '+(x.hold?'Diesen Monat bleibt der volle Safety-Beitrag für den Notgroschen vorgesehen.':'Deine Safety-Mittel werden nach deiner Einstellung verteilt.')+'</div>':'<p class="info">'+(eta!==null?'Bei gleichbleibendem Einkommen und '+euro(x.b.s)+' monatlich fehlen rechnerisch noch '+eta+' Monatsbeiträge.':'Momentan ist kein Safety-Beitrag eingeplant.')+' Dein tatsächlicher Stand ändert sich nur durch deine Eingabe.</p>')+'<p class="info">Safety-Konto: <b>'+esc(accountName(state.budgetAccounts.s))+'</b></p><button class="textbtn" data-tab="distribute">Kontozuordnung ändern ↗</button></section><section class="card">'+cardHead('Safety flexibel verteilen','Du entscheidest über die 15 %.')+'<div class="splitlabels"><span>Wealth<b>'+state.share+' %</b></span><span style="text-align:right">Lifestyle<b>'+(100-state.share)+' %</b></span></div><input type="range" min="0" max="100" step="1" value="'+state.share+'" id="splitrange" aria-label="Wealth-Anteil der Safety-Verteilung"><div class="pair"><span>Für Wealth</span><b id="splitgrowth">'+euro(x.base.s*state.share/100)+'</b></div><div class="pair"><span>Für Lifestyle</span><b id="splitrewards">'+euro(x.base.s*(1-state.share/100))+'</b></div><div class="rule"></div><label class="switchrow"><span><b>Schon vor vollem Notgroschen verteilen</b><br><small>Sonst wird die Aufteilung erst nach Zielerreichung aktiv.</small></span><input type="checkbox" id="early" '+(state.early?'checked':'')+'></label>'+(x.full?'<label class="switchrow"><span><b>Ziel erst diesen Monat erreicht</b><br><small>Diesen Monat fließt noch der volle Beitrag in den Notgroschen.</small></span><input type="checkbox" id="hold" '+(x.hold?'checked':'')+'></label>':'')+'<div class="status '+(x.hold?'hold':'')+'">'+(x.hold?'Im '+monthLabel(month())+' bleiben '+euro(x.base.s)+' vollständig für Safety vorgesehen. Die Aufteilung wird ab dem Folgemonat aktiv.':x.distributing?'Aufteilung aktiv: '+euro(x.base.s*state.share/100)+' zusätzlich für Wealth und '+euro(x.base.s*(1-state.share/100))+' zusätzlich für Lifestyle.':'Aufteilung vorgemerkt. Aktuell sind '+euro(x.base.s)+' monatlich für den Notgroschen vorgesehen.')+'</div><p class="info">Beim erstmaligen Erreichen des Zielbetrags bleibt der volle Monatsbeitrag für den Notgroschen reserviert. Die Umverteilung erscheint automatisch im Einkommensverteiler.</p></section></div>'}
function projection(year,rate){const q=Math.pow(1+rate,1/12)-1,n=year*12;return state.portfolio*Math.pow(1+q,n)+state.rate*(Math.pow(1+q,n)-1)/q}
