function updateSharedPreview(){const checkbox=document.getElementById('shared'),preview=document.getElementById('sharepreview');if(!checkbox||!preview)return;const amount=parseNumber(document.getElementById('entryamount').value);document.getElementById('amountlabel').textContent=checkbox.checked?'Monatlicher Gesamtbetrag':'Monatlicher Betrag';preview.classList.toggle('hidden',!checkbox.checked);preview.textContent=Number.isFinite(amount)?'Dein monatlicher Anteil: '+euro(personalAmount({amount,shared:true}))+' · von '+euro(amount)+' gesamt':'Gib den gemeinsamen Gesamtbetrag ein. Dein Anteil wird automatisch halbiert.';}
