document.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.accountedit){openAccountModal(btn.dataset.accountedit);return}if(btn.dataset.accountdelete){openDeleteAccount(btn.dataset.accountdelete);return}if(btn.dataset.tab){tab=btn.dataset.tab;render();window.scrollTo({top:0,behavior:'smooth'});return}if(btn.dataset.add){openModal(btn.dataset.add);return}if(btn.dataset.edit){const [key,id]=btn.dataset.edit.split(':');openModal(key,Number(id));return}if(btn.dataset.safety){state.safety=Number(btn.dataset.safety);save();return}switch(btn.dataset.action){case 'theme':state.theme=resolvedTheme()==='dark'?'light':'dark';save();break;case 'addaccount':openAccountModal();break;case 'confirmdeleteaccount':{const id=btn.dataset.id,target=document.getElementById('replacementaccount').value;if(removeAccount(id,target)){closeModal();save();toast('Konto entfernt und Zuordnungen übernommen.')}break}case 'close':closeModal();break;case 'delete':if(editing){state[editing.key]=state[editing.key].filter(r=>r.id!==editing.id);closeModal();save()}break;case 'clear':previousFocus=btn;document.getElementById('modalroot').innerHTML='<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialogtitle"><div class="modalhead"><h2 id="dialogtitle">Dein eigener Plan</h2><button class="editbtn" data-action="close" aria-label="Schließen">'+icon('close')+'</button></div><p class="subtitle">Die Beispieldaten werden entfernt. Du startest mit einer leeren Planung. Die Standardkonten stehen direkt zur Auswahl. Du kannst vorher eine Sicherung exportieren.</p><div class="modalactions"><button class="primary" data-action="confirmclear">Leere Planung starten</button></div></section></div>';focusModal();break;case 'confirmclear':{const theme=state.theme;state=fresh();state.theme=theme;}tab='plan';closeModal();save();break;case 'export':{flushEdits();applyContributions();const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='Vermoegensaufbau-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),5000);toast('Sicherung mit allen Kontozuordnungen erstellt.');break}case 'import':document.getElementById('importfile').click();break;case 'confirmimport':if(pendingImport){const imported=pendingImport;closeModal();state=imported;save();toast('Deine Sicherung wurde wiederhergestellt.')}break}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='shared'){updatePaymentPreview();return}if(el.name==='frequency'){updatePaymentPreview();return}if(el.id==='installment'){if(el.checked){const r=document.querySelector('input[name="frequency"][value="1"]');if(r)r.checked=true;}updatePaymentPreview();document.getElementById('dates').classList.toggle('hidden',!el.checked);updateInstallmentPreview();return}if(el.id==='startmonth'||el.id==='duration'){updateInstallmentPreview();return}if(el.dataset.number){const v=parseNumber(el.value);if(!Number.isFinite(v)||v<0||v>1e12){toast('Bitte einen gültigen Betrag eingeben, z. B. 125,50.');render();return}applyContributions();const before=calc();state[el.dataset.number]=v;if(el.dataset.number==='reserve'&&!before.full&&calc().full)state.hold=month();save();return}if(el.dataset.budgetaccount){state.budgetAccounts[el.dataset.budgetaccount]=el.value;save();return}if(el.id==='etfaccount'){state.etfAccount=el.value;save();return}if(el.id==='early'){state.early=el.checked;save()}if(el.id==='hold'){state.hold=el.checked?month():'';save()}if(el.id==='splitrange'){state.share=Number(el.value);save()}if(el.id==='yearrange'){state.years=Number(el.value);save()}});
document.addEventListener('focusin',e=>{if(e.target.id==='entryamount'&&parseNumber(e.target.value)===0)e.target.select()});
document.addEventListener('input',e=>{if(e.target.id==='startmonth'||e.target.id==='duration')updateInstallmentPreview();if(e.target.id==='entryamount'||e.target.id==='shared')updatePaymentPreview();if(e.target.id==='splitrange'){const v=Number(e.target.value),s=calc().base.s;document.querySelector('.splitlabels').innerHTML='<span>Wealth<b>'+v+' %</b></span><span style="text-align:right">Lifestyle<b>'+(100-v)+' %</b></span>';document.getElementById('splitgrowth').textContent=euro(s*v/100);document.getElementById('splitrewards').textContent=euro(s*(1-v/100))}if(e.target.id==='yearrange')document.getElementById('yearlabel').textContent=e.target.value+' Jahre'});
document.getElementById('importfile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error();const data=upgrade(window.Vault?await window.Vault.importFile(file):JSON.parse(await file.text()));if(window.Vault?.locked)return;if(!valid(data))throw Error();pendingImport=data;previousFocus=document.activeElement;document.getElementById('modalroot').innerHTML='<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialogtitle"><div class="modalhead"><h2 id="dialogtitle">Sicherung importieren?</h2><button class="editbtn" data-action="close" aria-label="Schließen">'+icon('close')+'</button></div><p class="subtitle">Deine aktuelle Planung wird durch diese Sicherung ersetzt. Sicherungen aus Version 1 und 2 werden automatisch übernommen. Aktive automatische Sparraten der Sicherung werden beim Öffnen fortgeschrieben; bitte nach dem Import prüfen.</p><div class="modalactions"><button class="secondary" data-action="close">Abbrechen</button><button class="primary" data-action="confirmimport">Planung ersetzen</button></div></section></div>';focusModal()}catch(err){toast('Diese Datei ist keine gültige Vermögensaufbau-Sicherung.')}e.target.value=''});
document.addEventListener('keydown',e=>{const modal=document.querySelector('.modal');if(!modal)return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const nodes=[...modal.querySelectorAll('button,input,select')].filter(n=>!n.disabled&&n.offsetParent!==null),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.getElementById('brandicon').innerHTML=icon('trend',21);document.getElementById('exporticon').innerHTML=icon('download',17);document.getElementById('importicon').innerHTML=icon('upload',17);
let lastMonth=month();document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&state)flushEdits();if(document.visibilityState==='visible'&&lastMonth!==month()){lastMonth=month();render()}});
